def _raises_value_error(thunk):
    try:
        thunk()
        return False
    except ValueError:
        return True

def sum_str_lengths(L):
    total = 0
    for i in L:
        if type(i) == str:
            total += len(i)
        elif type(i) == list:
            for e in i:
                if type(e) == str:
                    total += len(e)
                else:
                    raise ValueError
        else:
            raise ValueError
    return total
